typedef unsigned int u_int;

struct z_stream
{
  unsigned char *next_in;
  u_int avail_in;
};

class os_file
{
public:
  int read(void *, int, bool);
};

extern "C" int sprintf(char *, const char *, ...);
extern "C" int inflate(z_stream *, int);
extern "C" int sceCdSync(int);

#define MAX_INPUT_WINDOW_SIZE (128 * 1024 + 1)
#define Z_SYNC_FLUSH 2
#define assert(x) ((void)0)
#define verify(x) ((void)0)
#define NEXT_READ \
  in_remaining -= \
    (this_read = ((in_remaining > (int)readSize) \
      ? readSize : in_remaining))

class zip_filter
{
public:
  static unsigned char input_window[];
  static z_stream zip_stream;
  static unsigned int readSize;
  static void async_filter(os_file *io, int in_remaining);
};

void zip_filter::async_filter(os_file *io, int in_remaining)
{
  int this_read = 0;
  unsigned char *input_window_1 = input_window;
  unsigned char *input_window_2 =
    input_window + (MAX_INPUT_WINDOW_SIZE);
  int ret_val, actually_read;
  char error_txt[20];
  NEXT_READ;

  actually_read = io->read(input_window_1, this_read, false);
  sprintf(error_txt, "%d", actually_read);
  verify(actually_read == this_read);

  while (1)
  {
    assert(zip_stream.avail_in == 0);
    zip_stream.next_in = input_window_1;
    zip_stream.avail_in = this_read;
    NEXT_READ;
    if (this_read)
    {
      actually_read = io->read(input_window_2, this_read, true);
      sprintf(error_txt, "%d", actually_read);
      verify(actually_read == this_read);
    }
    else
    {
      sceCdSync(0);
    }

    ret_val = inflate(&zip_stream, Z_SYNC_FLUSH);
    sprintf(error_txt, "%d", ret_val);
    assert(ret_val == 0 || ret_val == 1);

    if (this_read)
    {
      assert(zip_stream.avail_in == 0);
      zip_stream.next_in = input_window_2;
      zip_stream.avail_in = this_read;
      NEXT_READ;
      if (this_read)
      {
        actually_read = io->read(input_window_1, this_read, true);
        sprintf(error_txt, "%d", actually_read);
        verify(actually_read == this_read);
      }
      else
      {
        sceCdSync(0);
      }

      ret_val = inflate(&zip_stream, Z_SYNC_FLUSH);
      sprintf(error_txt, "%d", ret_val);
      assert(ret_val == 0 || ret_val == 1);

      if (!this_read)
        break;
    }
    else
      break;
  }
}
